import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"6. 生命周期与权限求值","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/tmpa-core-specification-s0.6/part-04.md","filePath":"zh/publications/tmpa-core-specification-s0.6/part-04.md","lastUpdated":1786288964000}'),i={name:"zh/publications/tmpa-core-specification-s0.6/part-04.md"};function s(n,e,r,c,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h2 id="_5-3-纳入考虑的威胁" tabindex="-1">5.3 纳入考虑的威胁 <a class="header-anchor" href="#_5-3-纳入考虑的威胁" aria-label="Permalink to &quot;5.3 纳入考虑的威胁&quot;">​</a></h2><p>符合规范的实现 <strong>SHOULD</strong> 考虑：身份冒充、未授权角色声明、对象篡改、有效对象重放、非法生命周期迁移、必需证据遗漏、首次发布时伪造结构正确但事实错误的证据、通过冲突对象进行双重陈述、受损工具或 Connector、导致越权动作的 Prompt Injection、证据删除或隐匿、时钟偏差与时间戳操纵、由错误/过期/对抗性审计结论触发的自动修复、扩大而非收敛权限的传递委托、能力组合形成越权结果、过期或撤销不足的委托证据、合法单步组合成非法路径，以及由同一模型、控制器、凭证、Host 或管理主体控制的名义独立复核者。</p><h2 id="_5-4-恶意参与者与存储表面受损" tabindex="-1">5.4 恶意参与者与存储表面受损 <a class="header-anchor" href="#_5-4-恶意参与者与存储表面受损" aria-label="Permalink to &quot;5.4 恶意参与者与存储表面受损&quot;">​</a></h2><p>TMPA Core 不假设所有参与者诚实。实现 <strong>MUST</strong> 保留归属、冲突对象、被拒迁移与验证问题，使不当行为可以被发现或调查。</p><h3 id="首次发布时结构正确但事实错误的证据" tabindex="-1">首次发布时结构正确但事实错误的证据 <a class="header-anchor" href="#首次发布时结构正确但事实错误的证据" aria-label="Permalink to &quot;首次发布时结构正确但事实错误的证据&quot;">​</a></h3><p>TMPA 区分<strong>首次发布时的伪造</strong>与发布后的篡改。恶意、受损或错误的参与者可能发布 Schema 有效、Digest 一致、生命周期合法、甚至签名正确的 <code>REPORT</code>、<code>REVIEW</code> 或 <code>DECISION</code>，但其中事实声明仍然错误。Core 验证可以建立结构有效性、连续性、声明权限与已发布字节完整性，不能由这些属性推导语义真实性。</p><p>事实保证需要与声明相适配的证据 Profile，例如工具回执、外部可验证输出、可复现执行、测试结果、独立数据源、在真正独立安全主体下的交叉复核或人工批准。执行者与复核者共享同一受损控制器、凭证、证据源或管理主体时，名义职责分离可能产生相关性伪造。TMPA 可以保留 Provenance、矛盾与后续更正，但不能检测隐蔽串谋，也不保证首次发布声明为真。</p><p>FCoP 把文件系统纳入协议边界，因此存在特定攻击面：有直接写权限的参与者可能把对象直接放入 <code>_lifecycle/done/</code>、修改已发布工件、删除证据、重放旧文件，或制造路径/事件不一致。文件存在本身 <strong>MUST NOT</strong> 被视为有效性证明。</p><p>Reader <strong>SHOULD</strong> 至少区分：</p><ol><li><strong>未授权插入：</strong> 工件出现在生命周期位置，但没有有效创建者、角色分配、前驱状态或迁移记录；</li><li><strong>发布后变更：</strong> 内容与记录的 Digest 或签名不一致；</li><li><strong>状态证据分歧：</strong> 生命周期路径、迁移历史、引用与预期配对工件互不一致。</li></ol><p>这些攻击只能在部署保护或独立验证身份绑定、完整性记录、只增事件与存储历史的范围内被检测。如果攻击者能够同时改写工件及全部可信完整性、身份与审计记录，本地文件系统视图无法建立真实历史。更强部署 <strong>MAY</strong> 增加受限写权限、只增或版本化存储、远程公证、透明日志、复制或密码学签名；这些属于最低 FCoP 文件 Profile 之外的部署控制。</p><p>TMPA Core <strong>MUST NOT</strong> 被描述为提供拜占庭共识。若身份提供方、角色权限、密钥注册表、可信存储边界和验证器均受损，TMPA 无法保证真实历史。需要拜占庭容错的部署 <strong>MUST</strong> 增加外部共识、复制、公证或透明日志机制。</p><p>Inspect-only 审计 Profile 可以缩小一次失败的影响：受损 Inspector 可以生成误导性发现或建议，但审计功能不直接修改受治理业务状态。这不是完整防护；建议的 Provenance、复核、批准与执行证据仍然 <strong>MUST</strong> 保留。</p><h2 id="_5-5-角色与身份分离层级" tabindex="-1">5.5 角色与身份分离层级 <a class="header-anchor" href="#_5-5-角色与身份分离层级" aria-label="Permalink to &quot;5.5 角色与身份分离层级&quot;">​</a></h2><p>TMPA 区分逻辑责任分离与安全域分离：</p><ol><li><strong>Prompt 级角色分离：</strong> 参与者使用不同角色指令，但可以共享 Runtime、凭证与存储权限；</li><li><strong>进程级身份分离：</strong> 不同 Agent/进程实例具有稳定 Runtime 身份与独立可归属 Session；</li><li><strong>凭证级分离：</strong> 使用可独立验证、限制和撤销的不同凭证、密钥或委托授权；</li><li><strong>Host 级隔离：</strong> OS 账户、容器、Sandbox 或强制访问控制阻止参与者直接修改他人受保护证据；</li><li><strong>管理域分离：</strong> 独立组织、信任根、审计服务或透明系统降低单一管理员改写全部记录的风险。</li></ol><p>Prompt 级分离可以支持流程清晰，但不是安全边界。进程级身份改善归属，但不能阻止共享凭证或跨进程存储修改。声称独立复核、认证责任或防篡改的部署 <strong>MUST</strong> 采用与威胁模型相称的凭证、Host 或管理域控制。</p><p>最低 FCoP Profile 下的文件名、文件所有者、角色文档或 Frontmatter <code>sender</code> 都只是<strong>声明性归属</strong>。只有验证执行进程、凭证/密钥、有效角色分配与受保护写入边界之间的绑定后，它才成为已验证归属。由同一模型、服务账户或无限制 Host 控制的多个逻辑角色 <strong>MUST NOT</strong> 仅因 Prompt 或文件名不同就被描述为独立安全主体。</p><p>已验证委托链还 <strong>MUST</strong> 区分委托主体、委托任务/意图、授予能力集合、权限衰减规则、时间有效性、执行次数或撤销条件，以及每次下游再委托。既有 <code>TASK</code>、<code>REPORT</code> 或角色标签不会自动授权新动作，除非有效身份与授权 Profile 明确认可其为当前委托证据。</p><h2 id="_5-6-ai-agent-身份" tabindex="-1">5.6 AI Agent 身份 <a class="header-anchor" href="#_5-6-ai-agent-身份" aria-label="Permalink to &quot;5.6 AI Agent 身份&quot;">​</a></h2><p>AI Agent <strong>MUST NOT</strong> 被视为自认证法律身份。FCoP 仍要求 Agent 获得自己能够读取的显式运行身份：角色、团队上下文、责任边界与当前工作范围。运行身份背后的权限来自人类或组织主体、部署身份、角色分配权限、Runtime 凭证与策略范围。</p><p>身份记录 <strong>SHOULD</strong> 分开表示：组织主体、人类授权者、Agent 实例、模型或 Runtime 版本、有效角色、委托权限、凭证或密钥 ID。这样可以避免把 Agent 动作只归属于借用的人类账户或服务账户。</p><h2 id="_5-7-安全声明" tabindex="-1">5.7 安全声明 <a class="header-anchor" href="#_5-7-安全声明" aria-label="Permalink to &quot;5.7 安全声明&quot;">​</a></h2><p>实现 <strong>MUST</strong> 明确声明其支持的保证层级：</p><table tabindex="0"><thead><tr><th>声明</th><th>最低要求</th></tr></thead><tbody><tr><td>文本可追踪性</td><td>持久规范对象与引用</td></tr><tr><td>篡改检测</td><td>对保留或可信完整性元数据执行确定性 Digest 验证</td></tr><tr><td>认证完整性</td><td>已验证签名与可信密钥绑定</td></tr><tr><td>授权执行</td><td>已验证角色分配与动作策略</td></tr><tr><td>语义声明验证</td><td>Core 之外的声明特定证据、可复现输出或独立领域验证</td></tr><tr><td>不可否认</td><td>TMPA Core 之外的法律与密码学 Profile</td></tr><tr><td>拜占庭韧性</td><td>外部共识或等价机制</td></tr></tbody></table><p>实现 <strong>MUST NOT</strong> 声称超出实际部署控制的更强属性。</p><hr><h1 id="_6-生命周期与权限求值" tabindex="-1">6. 生命周期与权限求值 <a class="header-anchor" href="#_6-生命周期与权限求值" aria-label="Permalink to &quot;6. 生命周期与权限求值&quot;">​</a></h1><h2 id="_6-1-必需注册表" tabindex="-1">6.1 必需注册表 <a class="header-anchor" href="#_6-1-必需注册表" aria-label="Permalink to &quot;6.1 必需注册表&quot;">​</a></h2><p>实现 Profile 发布带版本的生命周期、角色与关系注册表。生命周期注册项包含：Profile ID 与版本、状态集合、初始与终止状态、动作集合、合法 <code>from/action/to</code> 元组、每项动作允许的角色、必需引用与前置条件、职责分离规则，以及任何授权重新打开或恢复规则。角色注册项包含：角色 ID、Assignment 对象类型、允许的文档类型和生命周期动作、Scope 维度、不兼容角色、分配权限方与撤销语义。关系注册项声明关系属于顺序、非顺序、必需或无环关系。</p><p>注册表字节是重建输入。因此，注册表版本与 Digest 属于 Reader 输入契约和一致性报告；修改注册表而保留原 ID 不会得到同一个固定 Profile。</p><h2 id="_6-2-迁移求值顺序" tabindex="-1">6.2 迁移求值顺序 <a class="header-anchor" href="#_6-2-迁移求值顺序" aria-label="Permalink to &quot;6.2 迁移求值顺序&quot;">​</a></h2><p>对于候选迁移 <code>x</code>、Profile <code>P</code>、规范候选集合 <code>C</code> 和当前重建状态 <code>s</code>，按以下固定顺序求值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EVALUATE_TRANSITION(x, s, C, P):</span></span>
<span class="line"><span>  1. 验证对象 Schema、类型规则、身份与完整性</span></span>
<span class="line"><span>  2. 解析受治理工作项、主载体与生命周期 Profile</span></span>
<span class="line"><span>  3. 从已接受前驱证据重建唯一当前状态</span></span>
<span class="line"><span>  4. 验证 x.from 等于该当前状态</span></span>
<span class="line"><span>  5. 验证 (x.from, x.action, x.to) 是合法迁移元组</span></span>
<span class="line"><span>  6. 解析有效角色 Assignment 并验证动作 Scope</span></span>
<span class="line"><span>  7. 求值职责分离规则与授权例外</span></span>
<span class="line"><span>  8. 解析必需引用、前置条件与证据</span></span>
<span class="line"><span>  9. 赋予 valid、invalid 或 undetermined，并生成规范问题</span></span>
<span class="line"><span> 10. 仅当迁移判断为 valid 时应用 x.to</span></span></code></pre></div><p>已证明的违规——例如非法元组、已撤销权限、超出 Scope 的动作或禁止的角色组合——产生 <code>invalid</code>。证据缺失——例如 Assignment 不可用、前驱未解析、必需引用缺失或当前状态有歧义——产生 <code>undetermined</code>。只有 <code>valid</code> 迁移改变权威生命周期投影。</p><h2 id="_6-3-状态重建" tabindex="-1">6.3 状态重建 <a class="header-anchor" href="#_6-3-状态重建" aria-label="Permalink to &quot;6.3 状态重建&quot;">​</a></h2><p>对每个受治理工作项，Reader 在接受有效主载体后从生命周期 Profile 的初始状态开始，再按写者流序号和声明顺序依赖建立的偏序求值迁移对象。不得使用挂钟时间选择下一项迁移。</p><p>如果两个有效迁移候选消费同一来源状态，效果互不兼容，且不存在顺序关系或授权解决，则当前状态为 <code>undetermined</code>，视图为 <code>disputed</code>。Reader 保留两个分支，不选择最后到达者。终止状态保持终止，除非生命周期注册表显式定义授权恢复或重新打开迁移。</p><h2 id="_6-4-权限时间与撤销" tabindex="-1">6.4 权限时间与撤销 <a class="header-anchor" href="#_6-4-权限时间与撤销" aria-label="Permalink to &quot;6.4 权限时间与撤销&quot;">​</a></h2><p>Reader 针对适用于该动作的 Assignment 与撤销证据验证权限。<code>created_at</code> 本身不是可信授权时钟。进行时间敏感权限声明的 Profile 要定义用于判断 Assignment 是否有效的可信时间或序列证据。</p><p>证据证明权限无效，动作判断为 <code>invalid</code>；无法确定相关权限区间，动作判断为 <code>undetermined</code>。Profile 还声明撤销是前瞻性的，还是可以使已定义类别的早期动作无效；Reader 不得虚构追溯效力。</p><h1 id="_7-三值治理逻辑" tabindex="-1">7. 三值治理逻辑 <a class="header-anchor" href="#_7-三值治理逻辑" aria-label="Permalink to &quot;7. 三值治理逻辑&quot;">​</a></h1><h2 id="_7-1-判断域" tabindex="-1">7.1 判断域 <a class="header-anchor" href="#_7-1-判断域" aria-label="Permalink to &quot;7.1 判断域&quot;">​</a></h2><p>TMPA Core 的规范判断域为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>J = { valid, invalid, undetermined }</span></span></code></pre></div><p><code>valid</code> 表示固定输入和适用规则证明要求成立；<code>invalid</code> 表示它们证明存在违规或拒绝；<code>undetermined</code> 表示证据缺失、冲突或尚未解决，因而无法得出二值结论。<code>undetermined</code> 不是 <code>invalid</code> 的委婉说法，也不是默认接受。</p><h2 id="_7-2-原子分类规则" tabindex="-1">7.2 原子分类规则 <a class="header-anchor" href="#_7-2-原子分类规则" aria-label="Permalink to &quot;7.2 原子分类规则&quot;">​</a></h2><p>Reader <strong>SHALL</strong> 按下表分类原子检查：</p><table tabindex="0"><thead><tr><th>条件</th><th>判断</th><th>主要视图原因</th></tr></thead><tbody><tr><td>要求已证明满足</td><td><code>valid</code></td><td><code>authoritative</code></td></tr><tr><td>规则已证明被违反</td><td><code>invalid</code></td><td><code>rejected</code> 或 <code>quarantined</code></td></tr><tr><td>必需证据缺失或无法读取</td><td><code>undetermined</code></td><td><code>partial</code></td></tr><tr><td>多个有效候选互相矛盾且无授权解决</td><td><code>undetermined</code></td><td><code>disputed</code></td></tr><tr><td>必需人工决定尚未发布</td><td><code>undetermined</code></td><td><code>pending_human</code></td></tr><tr><td>可选签名在 Core 下缺失</td><td>Core 判断不变</td><td><code>unauthenticated</code> 保证标记</td></tr><tr><td>认证 Profile 要求的认证无法建立</td><td>按已发布 Profile 为 <code>undetermined</code> 或 <code>invalid</code></td><td><code>unauthenticated</code> 或 <code>quarantined</code></td></tr></tbody></table><p><code>unauthenticated</code> 是认证状态，而不是第四个治理判断值。要求认证完整性的 Profile 中，缺失认证证据产生 <code>undetermined</code>；已证明签名或身份无效产生 <code>invalid</code>。</p><h2 id="_7-3-组合规则" tabindex="-1">7.3 组合规则 <a class="header-anchor" href="#_7-3-组合规则" aria-label="Permalink to &quot;7.3 组合规则&quot;">​</a></h2><p>对于全部条件都必须满足的合取 <code>ALL(a,b)</code>，以及至少一个条件必须满足的析取 <code>ANY(a,b)</code>，Reader <strong>SHALL</strong> 使用下表：</p><table tabindex="0"><thead><tr><th>a</th><th>b</th><th><code>ALL(a,b)</code></th><th><code>ANY(a,b)</code></th></tr></thead><tbody><tr><td><code>valid</code></td><td><code>valid</code></td><td><code>valid</code></td><td><code>valid</code></td></tr><tr><td><code>valid</code></td><td><code>invalid</code></td><td><code>invalid</code></td><td><code>valid</code></td></tr><tr><td><code>valid</code></td><td><code>undetermined</code></td><td><code>undetermined</code></td><td><code>valid</code></td></tr><tr><td><code>invalid</code></td><td><code>valid</code></td><td><code>invalid</code></td><td><code>valid</code></td></tr><tr><td><code>invalid</code></td><td><code>invalid</code></td><td><code>invalid</code></td><td><code>invalid</code></td></tr><tr><td><code>invalid</code></td><td><code>undetermined</code></td><td><code>invalid</code></td><td><code>undetermined</code></td></tr><tr><td><code>undetermined</code></td><td><code>valid</code></td><td><code>undetermined</code></td><td><code>valid</code></td></tr><tr><td><code>undetermined</code></td><td><code>invalid</code></td><td><code>invalid</code></td><td><code>undetermined</code></td></tr><tr><td><code>undetermined</code></td><td><code>undetermined</code></td><td><code>undetermined</code></td><td><code>undetermined</code></td></tr></tbody></table><p>必需依赖为 <code>invalid</code> 时，依赖的接受条件为 <code>invalid</code>；必需依赖为 <code>undetermined</code> 时，依赖结论 <strong>SHALL</strong> 保持 <code>undetermined</code>。互相矛盾的有效结论不会相互抵消，也不会变成 <code>invalid</code>；它们形成 <code>undetermined</code> 的争议结论。只有解决对象本身有效、已授权并显式引用所解决的冲突时，解决才改变结论。</p><p>Profile <strong>MAY</strong> 定义领域特定聚合，但必须发布真值表，且不得把缺失或冲突的强制证据直接映射为 <code>valid</code>。</p><h2 id="_7-4-判断与视图映射" tabindex="-1">7.4 判断与视图映射 <a class="header-anchor" href="#_7-4-判断与视图映射" aria-label="Permalink to &quot;7.4 判断与视图映射&quot;">​</a></h2><p>判断是语义；视图状态解释运行原因。<code>valid</code> 映射为 <code>authoritative</code>。动作 <code>invalid</code> 映射为 <code>rejected</code>；证据或子图被排除时映射为 <code>quarantined</code>。<code>undetermined</code> 根据规范问题原因映射为 <code>disputed</code>、<code>partial</code> 或 <code>pending_human</code>。</p><p>一个主体有多个原因时，全部原因都保留在问题集合中。需要一个主视图标签时，按 <code>quarantined</code> → <code>rejected</code> → <code>disputed</code> → <code>partial</code> → <code>pending_human</code> → <code>authoritative</code> 选择。认证是独立保证状态，不形成第四个语义判断。</p><h1 id="_8-reader-输入与输出契约" tabindex="-1">8. Reader 输入与输出契约 <a class="header-anchor" href="#_8-reader-输入与输出契约" aria-label="Permalink to &quot;8. Reader 输入与输出契约&quot;">​</a></h1><h2 id="_8-1-输入-bundle" tabindex="-1">8.1 输入 Bundle <a class="header-anchor" href="#_8-1-输入-bundle" aria-label="Permalink to &quot;8.1 输入 Bundle&quot;">​</a></h2><p>一次可复现 Reader 运行 <strong>SHALL</strong> 固定并记录以下输入：</p><ul><li>TMPA Core 对象 Schema 版本与 Digest；</li><li>一致性 Profile ID、版本与 Digest；</li><li>类型、生命周期、角色、关系、完整性和规范化注册表的版本与 Digest；</li><li>有限来源候选多重集合，其中每个候选具有稳定 <code>source_id</code>、媒体类型、精确字节与字节 Digest；</li><li>声明的信任根与认证策略；</li><li>Reader 实现标识与版本；</li><li>规范输出格式版本；</li><li>任何实现扩展，以及扩展是否影响规范语义。</li></ul><p>只有以上输入相等的两次运行才能用于 C11 比较。环境特定 Locator、发现时间戳、日志顺序、内存地址与本地化诊断不是规范输入。</p><h2 id="_8-2-规范结果" tabindex="-1">8.2 规范结果 <a class="header-anchor" href="#_8-2-规范结果" aria-label="Permalink to &quot;8.2 规范结果&quot;">​</a></h2><p>Reader <strong>SHALL</strong> 输出至少包含以下字段的规范结果 Envelope：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;core_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;S0.6&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;output_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;profile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source_set_digest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:&lt;hex&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;judgment&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;valid | invalid | undetermined&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;view_state&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;authoritative | rejected | quarantined | partial | disputed | pending_human&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;nodes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;edges&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;issues&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>每个节点和边 <strong>SHALL</strong> 包含稳定 ID 与其来源对象 ID。每个问题 <strong>SHALL</strong> 包含稳定 <code>issue_id</code> 与 <code>source_id</code>；解析产生来源对象 ID 时还记录 <code>source_object_id</code>。节点 <strong>SHOULD</strong> 另记录规范 Digest、受治理工作项 ID、主载体 ID、类型、流位置、判断、视图状态与保留的来源 ID；边 <strong>SHOULD</strong> 记录关系与排序语义；问题 <strong>SHALL</strong> 记录代码和严重级别，并 <strong>SHOULD</strong> 记录受影响判断、规范规则与确定性参数。</p><p>Core 问题代码为：<code>SCHEMA_INVALID</code>、<code>UNKNOWN_TYPE</code>、<code>INTEGRITY_MISMATCH</code>、<code>SIGNATURE_UNVERIFIED</code>、<code>DUPLICATE_ID_CONFLICT</code>、<code>PRIMARY_CARRIER_CONFLICT</code>、<code>STREAM_DUPLICATE_SEQUENCE</code>、<code>STREAM_GAP</code>、<code>AUTHORITY_UNDETERMINED</code>、<code>AUTHORITY_DENIED</code>、<code>SOD_VIOLATION</code>、<code>LIFECYCLE_UNDETERMINED</code>、<code>ILLEGAL_TRANSITION</code>、<code>MISSING_REFERENCE</code>、<code>PROHIBITED_CYCLE</code>、<code>UNRESOLVED_CONFLICT</code>、<code>CLAIM_EVIDENCE_MISSING</code>、<code>ACCEPTANCE_UNDETERMINED</code>、<code>HUMAN_APPROVAL_REQUIRED</code>、<code>CHILD_WORK_OPEN</code>、<code>RECIPROCITY_MISSING</code> 与 <code>STATE_EVIDENCE_CONFLICT</code>。Profile <strong>MAY</strong> 增加命名空间化代码，但不得重定义 Core 代码。</p><h2 id="_8-3-规范化与排序" tabindex="-1">8.3 规范化与排序 <a class="header-anchor" href="#_8-3-规范化与排序" aria-label="Permalink to &quot;8.3 规范化与排序&quot;">​</a></h2><p><code>source_set_digest</code> 按声明输出 Profile 从 <code>(source_id, byte_digest)</code> 对的确定性排序列表计算。节点按 <code>(id, source_object_id)</code> 排序；边按 <code>(source_id, relation, target_id, id)</code> 排序；问题按 <code>(severity, code, object_id, relation, target_id, issue_id)</code> 排序，其中严重级别顺序为 <code>critical</code>、<code>error</code>、<code>warning</code>、<code>info</code>。元组中不存在的字段按空字符串处理。</p><p><code>issue_id</code> <strong>SHALL</strong> 由 <code>(code, object_id, relation, target_id, profile_digest)</code> 的规范编码确定性导出。人类可读消息、Stack Trace、本地路径与执行时间戳排除在规范等价性之外。对象键、主体、保留的来源 ID、节点、边和问题在 Profile 定义规范化后按 Unicode 码点排序；依赖 Locale 的排序不得作为规范排序。</p><p>对于相同固定输入，规范结果序列化必须字节稳定。非规范日志与用户界面排序可以变化，但不得改变用于 C11 的结果 Envelope。</p><h2 id="_8-4-失败与部分输出" tabindex="-1">8.4 失败与部分输出 <a class="header-anchor" href="#_8-4-失败与部分输出" aria-label="Permalink to &quot;8.4 失败与部分输出&quot;">​</a></h2><p>即使某些候选格式错误或子图无效，Reader 仍返回规范结果与问题集合。只有固定 Profile、Schema、注册表 Bundle 或输出规范化契约无法加载或验证时，Reader 才可使整个调用失败。此类调用失败不同于 <code>invalid</code> 治理判断，并作为一致性运行错误报告。</p><h1 id="_9-tmpa-core-规范" tabindex="-1">9. TMPA Core 规范 <a class="header-anchor" href="#_9-tmpa-core-规范" aria-label="Permalink to &quot;9. TMPA Core 规范&quot;">​</a></h1><h2 id="_9-1-规范语言" tabindex="-1">9.1 规范语言 <a class="header-anchor" href="#_9-1-规范语言" aria-label="Permalink to &quot;9.1 规范语言&quot;">​</a></h2><p>术语 <strong>MUST</strong>、<strong>MUST NOT</strong>、<strong>SHALL</strong>、<strong>SHALL NOT</strong>、<strong>SHOULD</strong>、<strong>SHOULD NOT</strong> 与 <strong>MAY</strong> 定义一致性要求。MUST、MUST NOT、SHALL、SHALL NOT 表示强制要求。</p><p>本章之外的说明性示例、实现观察与未来工作陈述不产生额外 Core 要求，除非命名一致性 Profile 明确把它们纳入规范。</p><h2 id="_9-2-对象要求" tabindex="-1">9.2 对象要求 <a class="header-anchor" href="#_9-2-对象要求" aria-label="Permalink to &quot;9.2 对象要求&quot;">​</a></h2><p>每个治理对象 <strong>MUST</strong>：</p><ul><li>符合 TMPA Core Schema 与已发布的文档类型定义；</li><li>在其治理域内具有全局唯一 ID；</li><li>恰好具有一个声明创建者身份；</li><li>标识恰好一个责任角色；</li><li>标识一条写者流和一个正整数序号；</li><li>标识一个文档类型；</li><li>标识一个受治理工作项和恰好一个主载体 ID；</li><li>标识一个生命周期 Profile 与声明状态；</li><li>包含规范文本内容；</li><li>包含可为空的 <code>references</code> 数组；</li><li>包含完整性证据。</li></ul><p>符合规范的 Validator <strong>SHALL</strong> 强制验证 <code>created_at</code> 声明的 <code>date-time</code> 格式；只把格式当作注释不足以通过 C01。</p><p>记录生命周期迁移的对象类型 <strong>SHALL</strong> 包含完整的 <code>from</code>、<code>action</code>、<code>to</code> 元组。非迁移类型 <strong>SHALL NOT</strong> 使用该元组产生隐式状态变化。</p><p>已发布对象 <strong>SHALL</strong> 不可变。更正、拒绝、取代、回滚或解决 <strong>SHALL</strong> 创建新的对象或迁移记录，并 <strong>SHALL</strong> 保留旧证据。</p><p>Schema 有效性 <strong>SHALL NOT</strong> 被解释为 ID 唯一、角色授权、生命周期合法、引用有效、Digest 正确或身份已认证的证明。</p><p>面向任务的 Profile <strong>SHALL</strong> 为每个受治理工作项定义一个稳定主载体 ID。后续接受、报告、复核、决策、更正与恢复对象 <strong>SHALL</strong> 引用该载体或 Profile 定义的后继关系，不得创建同一任务的歧义可变副本。</p><p>每个已发布治理对象 <strong>SHALL</strong> 只有一个写者。其他参与者 <strong>SHALL</strong> 通过新的可归属对象或迁移记录响应，并 <strong>SHALL NOT</strong> 修改其他写者已发布对象的内容。</p><h2 id="_9-3-类型注册要求" tabindex="-1">9.3 类型注册要求 <a class="header-anchor" href="#_9-3-类型注册要求" aria-label="Permalink to &quot;9.3 类型注册要求&quot;">​</a></h2><p>符合规范的实现 <strong>SHALL</strong> 发布文档类型注册表。每个类型定义 <strong>SHALL</strong> 指明允许创建者角色、必填字段、允许引用关系、适用生命周期 Profile 与验证规则。</p><p>注册表 <strong>SHALL</strong> 具有稳定 ID、版本与字节 Digest。Reader <strong>SHALL</strong> 把结果绑定到该精确注册表修订。每个类型定义还 <strong>SHALL</strong> 指明该类型是否要求生命周期迁移元组。</p><p>文档 <strong>SHALL NOT</strong> 同时充当自己的独立复核或批准，除非实现 Profile 允许一个已记录例外，而且例外标识批准权限。</p><h2 id="_9-4-角色要求" tabindex="-1">9.4 角色要求 <a class="header-anchor" href="#_9-4-角色要求" aria-label="Permalink to &quot;9.4 角色要求&quot;">​</a></h2><p>角色声明 <strong>SHALL</strong> 根据对相关对象与动作有效的权威角色分配进行验证。参与者 <strong>SHALL NOT</strong> 在有效角色范围之外执行受保护动作。</p><p>声称职责分离的部署 <strong>SHALL</strong> 定义并执行同一受治理结果上的不兼容角色组合。</p><p>角色分配、撤销、委托与职责分离例外 <strong>SHOULD</strong> 自身表示为治理对象。</p><p>角色与权限求值 <strong>SHALL</strong> 遵循第 6.2 节的顺序。已证明拒绝或超出 Scope 的动作 <strong>SHALL</strong> 为 <code>invalid</code>；分配证据缺失或有歧义 <strong>SHALL</strong> 为 <code>undetermined</code>。</p>`,96)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
